INSERT INTO engagement.financial_templates (code, domain, kind, line, title, source_file, source_sheet, source_sha256, version, active) VALUES ('AUD_LOPCYMAT', 'FINANCIERA', 'LOPCYMAT', 'GENERAL', 'Cuestionario LOPCYMAT', 'Atributos Auditorias.xlsx', 'LOPCYMAT', 'd64ef5bedf01fe16bbabeee14aa7223a10a8851cca4414acdc36e7598c910c5a', 1, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO engagement.financial_criteria (template_code, source_id, section, subsection, criterion_text, sort_order, excel_row, metadata) VALUES
    ('AUD_LOPCYMAT', 'LOP-1.1', 'I. PSST y Servicios de Seguridad', NULL, '¿La entidad posee un Programa de Seguridad y Salud en el Trabajo (PSST) propio, adaptado a sus procesos y formalmente aprobado? (Art. 61 LOPCYMAT / NT-01-2008)', 1, 9, '{"block": "1", "block_title": "I. PSST y Servicios de Seguridad", "block_weight": 0.2, "number": "1.1"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-1.2', 'I. PSST y Servicios de Seguridad', NULL, '¿Existe identificación, evaluación y matriz de control de procesos peligrosos y riesgos en cada puesto de trabajo? (Art. 56 Num. 3 y 4 LOPCYMAT / NT-01-2008)', 2, 10, '{"block": "1", "block_title": "I. PSST y Servicios de Seguridad", "block_weight": 0.2, "number": "1.2"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-1.3', 'I. PSST y Servicios de Seguridad', NULL, '¿El centro cuenta con un Servicio de Seguridad y Salud en el Trabajo (SSST) propio o mancomunado operativo según la nómina? (Art. 39 y 40 LOPCYMAT / Art. 14 RP-LOPCYMAT)', 3, 11, '{"block": "1", "block_title": "I. PSST y Servicios de Seguridad", "block_weight": 0.2, "number": "1.3"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-2.1', 'II. Comité (CSSL) y Delegados', NULL, '¿Los Delegados de Prevención fueron electos por los trabajadores, poseen certificado de registro en INPSASEL y ejercen sus atribuciones? (Art. 41 y 42 LOPCYMAT)', 4, 13, '{"block": "2", "block_title": "II. Comité (CSSL) y Delegados", "block_weight": 0.15, "number": "2.1"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-2.2', 'II. Comité (CSSL) y Delegados', NULL, '¿Está constituido y formalmente registrado ante el INPSASEL el Comité de Seguridad y Salud Laboral (CSSL) de forma paritaria? (Art. 46 LOPCYMAT)', 5, 14, '{"block": "2", "block_title": "II. Comité (CSSL) y Delegados", "block_weight": 0.15, "number": "2.2"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-2.3', 'II. Comité (CSSL) y Delegados', NULL, '¿El CSSL se reúne periódicamente (mínimo una vez al mes) y mantiene el Libro de Actas con acuerdos y firmas al día? (Art. 48 LOPCYMAT)', 6, 15, '{"block": "2", "block_title": "II. Comité (CSSL) y Delegados", "block_weight": 0.15, "number": "2.3"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-3.1', 'III. Condiciones e Instalaciones', NULL, '¿Se realizan inspecciones periódicas documentadas en las instalaciones para detectar y corregir condiciones inseguras o insalubres? (Art. 40 Num. 4 LOPCYMAT)', 7, 17, '{"block": "3", "block_title": "III. Condiciones e Instalaciones", "block_weight": 0.25, "number": "3.1"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-3.2', 'III. Condiciones e Instalaciones', NULL, '¿Los puestos, pasillos y áreas comunes cumplen con condiciones óptimas de orden, limpieza, iluminación y ventilación? (Art. 59 Num. 1 y 2 LOPCYMAT)', 8, 18, '{"block": "3", "block_title": "III. Condiciones e Instalaciones", "block_weight": 0.25, "number": "3.2"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-3.3', 'III. Condiciones e Instalaciones', NULL, '¿El mobiliario (sillas, escritorios) y las herramientas cumplen con criterios ergonómicos ajustados a los trabajadores? (Art. 59 Num. 5 LOPCYMAT)', 9, 19, '{"block": "3", "block_title": "III. Condiciones e Instalaciones", "block_weight": 0.25, "number": "3.3"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-3.4', 'III. Condiciones e Instalaciones', NULL, '¿Las salas sanitarias y vestuarios están diferenciados por sexo, operativos y dotados de agua, jabón y papel higiénico suficientes? (Art. 59 Num. 3 LOPCYMAT)', 10, 20, '{"block": "3", "block_title": "III. Condiciones e Instalaciones", "block_weight": 0.25, "number": "3.4"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-3.5', 'III. Condiciones e Instalaciones', NULL, '¿Se garantiza el suministro continuo de agua potable para consumo y áreas higiénicas y dignas para la alimentación? (Art. 59 Num. 4 y Art. 56 Num. 6 LOPCYMAT)', 11, 21, '{"block": "3", "block_title": "III. Condiciones e Instalaciones", "block_weight": 0.25, "number": "3.5"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-4.1', 'IV. Vigilancia Salud, Formación y EPP', NULL, '¿Se mantiene el Sistema de Vigilancia Epidemiológica ejecutando los exámenes pre-empleo, periódicos, pre y post-vacacionales y post-empleo? (Art. 27 RP-LOPCYMAT)', 12, 23, '{"block": "4", "block_title": "IV. Vigilancia Salud, Formación y EPP", "block_weight": 0.2, "number": "4.1"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-4.2', 'IV. Vigilancia Salud, Formación y EPP', NULL, '¿Cada trabajador recibió y firmó por escrito la Notificación de Principios de Prevención y Condiciones Peligrosas de su puesto? (Art. 56 Num. 3 LOPCYMAT)', 13, 24, '{"block": "4", "block_title": "IV. Vigilancia Salud, Formación y EPP", "block_weight": 0.2, "number": "4.2"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-4.3', 'IV. Vigilancia Salud, Formación y EPP', NULL, '¿Se dota de forma gratuita con Equipos de Protección Personal (EPP) certificados, registrando constancia escrita de entrega y uso? (Art. 56 Num. 5 LOPCYMAT)', 14, 25, '{"block": "4", "block_title": "IV. Vigilancia Salud, Formación y EPP", "block_weight": 0.2, "number": "4.3"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-4.4', 'IV. Vigilancia Salud, Formación y EPP', NULL, '¿Se cumple el Programa de Educación Teórica-Práctica en seguridad y salud, garantizando un mínimo de 16 horas trimestrales por trabajador? (Art. 53 Num. 2 LOPCYMAT / Art. 208 RP-LOPCYMAT)', 15, 26, '{"block": "4", "block_title": "IV. Vigilancia Salud, Formación y EPP", "block_weight": 0.2, "number": "4.4"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-5.1', 'V. Emergencias y Protección', NULL, '¿Se cuenta con un Plan de Emergencias y Contingencias, manteniendo las vías de evacuación despejadas, iluminadas y señalizadas? (Art. 56 LOPCYMAT / COVENIN 1870)', 16, 28, '{"block": "5", "block_title": "V. Emergencias y Protección", "block_weight": 0.2, "number": "5.1"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-5.2', 'V. Emergencias y Protección', NULL, '¿Las instalaciones poseen extintores portátiles de incendio adecuados al tipo de riesgo (PQS / CO2), accesibles y señalizados? (COVENIN 1040 / COVENIN 810)', 17, 29, '{"block": "5", "block_title": "V. Emergencias y Protección", "block_weight": 0.2, "number": "5.2"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-5.3', 'V. Emergencias y Protección', NULL, '¿Los extintores y sistemas contra incendio tienen inspección, prueba hidrostática y etiqueta de recarga vigente? (COVENIN 3049 / COVENIN 1040)', 18, 30, '{"block": "5", "block_title": "V. Emergencias y Protección", "block_weight": 0.2, "number": "5.3"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-5.4', 'V. Emergencias y Protección', NULL, '¿Está conformada, entrenada y dotada la Brigada de Emergencias / Lucha Contra Incendios, ejecutando simulacros documentados? (Art. 40 Num. 11 LOPCYMAT)', 19, 31, '{"block": "5", "block_title": "V. Emergencias y Protección", "block_weight": 0.2, "number": "5.4"}'::jsonb),
    ('AUD_LOPCYMAT', 'LOP-5.5', 'V. Emergencias y Protección', NULL, '¿La entidad posee Certificado de Inspección de Seguridad contra Incendios (Bomberos) o Permiso de Habitabilidad vigente? (Ley Org. Servicio de Bomberos / Art. 56 LOPCYMAT)', 20, 32, '{"block": "5", "block_title": "V. Emergencias y Protección", "block_weight": 0.2, "number": "5.5"}'::jsonb)
INSERT INTO engagement.financial_templates (code, domain, kind, line, title, source_file, source_sheet, source_sha256, version, active) VALUES ('AUD_SERV_SUC', 'FINANCIERA', 'SERV_SUC', 'GENERAL', 'Administración y servicios en sucursales', 'Atributos Auditorias.xlsx', 'Servicios Sucursal', 'd64ef5bedf01fe16bbabeee14aa7223a10a8851cca4414acdc36e7598c910c5a', 1, TRUE) ON CONFLICT (code) DO NOTHING;
INSERT INTO engagement.financial_criteria (template_code, source_id, section, subsection, criterion_text, sort_order, excel_row, metadata) VALUES
    ('AUD_SERV_SUC', 'SS-1.1', '1. Infraestructura Física e Imagen', NULL, '¿La distribución física y funcional de la sucursal es adecuada para la operación diaria, facilitando el flujo libre de clientes y empleados?', 1, 9, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.2', '1. Infraestructura Física e Imagen', NULL, '¿La fachada, señalización externa y los avisos de identificación comercial se encuentran visibles y en buen estado de conservación?', 2, 10, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.3', '1. Infraestructura Física e Imagen', NULL, '¿El mobiliario de la zona de espera (sillas, butacas) es suficiente para la capacidad máxima de atención y se mantiene en buen estado?', 3, 11, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.4', '1. Infraestructura Física e Imagen', NULL, '¿La cartelera informativa institucional está actualizada, visible al público y cumple con los requerimientos legales vigentes?', 4, 12, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.5', '1. Infraestructura Física e Imagen', NULL, '¿El mantenimiento general (limpieza, pintura, iluminación y climatización) se ejecuta programadamente y es adecuado para la sucursal?', 5, 13, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.5"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.6', '1. Infraestructura Física e Imagen', NULL, '¿Las estaciones de trabajo del personal cuentan con las condiciones ergonómicas mínimas necesarias para sus labores?', 6, 14, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.6"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-1.7', '1. Infraestructura Física e Imagen', NULL, '¿Se dispone de un área de comedor/almuerzo independiente, limpia y dotada para el uso del personal que labora en la sucursal?', 7, 15, '{"block": "1", "block_title": "1. Infraestructura Física e Imagen", "block_weight": 0.1, "number": "1.7"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-2.1', '2. Atención al Cliente y Calidad', NULL, '¿El horario de trabajo y de atención al público se encuentra publicado y claramente visible en los accesos de la sucursal?', 8, 17, '{"block": "2", "block_title": "2. Atención al Cliente y Calidad", "block_weight": 0.15, "number": "2.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-2.2', '2. Atención al Cliente y Calidad', NULL, '¿La sucursal opera y cumple con el horario corrido o la jornada establecida, sin interrupción no autorizada de servicios al cliente?', 9, 18, '{"block": "2", "block_title": "2. Atención al Cliente y Calidad", "block_weight": 0.15, "number": "2.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-2.3', '2. Atención al Cliente y Calidad', NULL, '¿Se cuenta con un sistema (mecanizado, digital o manual normado) para la gestión ordenada de turnos y colas de atención?', 10, 19, '{"block": "2", "block_title": "2. Atención al Cliente y Calidad", "block_weight": 0.15, "number": "2.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-2.4', '2. Atención al Cliente y Calidad', NULL, '¿Se cumple formalmente con la atención prioritaria obligatoria para adultos mayores, personas con discapacidad y embarazadas?', 11, 20, '{"block": "2", "block_title": "2. Atención al Cliente y Calidad", "block_weight": 0.15, "number": "2.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-2.5', '2. Atención al Cliente y Calidad', NULL, '¿Se dispone de un mecanismo formal y accesible (buzón, libro o canal digital) para la recepción y trámite de reclamos de los usuarios?', 12, 21, '{"block": "2", "block_title": "2. Atención al Cliente y Calidad", "block_weight": 0.15, "number": "2.5"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-3.1', '3. Caja y Resguardo de Valores', NULL, '¿El área de caja se encuentra físicamente delimitada, separada del público y con mecanismos de acceso restringido?', 13, 23, '{"block": "3", "block_title": "3. Caja y Resguardo de Valores", "block_weight": 0.15, "number": "3.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-3.2', '3. Caja y Resguardo de Valores', NULL, '¿Se aplican procedimientos formales para el resguardo inmediato, arqueo y traslado seguro del efectivo/cheques recibidos en sucursal?', 14, 24, '{"block": "3", "block_title": "3. Caja y Resguardo de Valores", "block_weight": 0.15, "number": "3.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-3.3', '3. Caja y Resguardo de Valores', NULL, '¿Las taquillas de caja disponen de detectores operativos (luz ultravioleta/contadoras) para verificar la autenticidad de los billetes?', 15, 25, '{"block": "3", "block_title": "3. Caja y Resguardo de Valores", "block_weight": 0.15, "number": "3.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-3.4', '3. Caja y Resguardo de Valores', NULL, '¿Las llaves, combinaciones de caja fuerte y precintos de seguridad se custodian bajo el principio de control dual o segregación?', 16, 26, '{"block": "3", "block_title": "3. Caja y Resguardo de Valores", "block_weight": 0.15, "number": "3.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-4.1', '4. Gestión del Personal (RRHH)', NULL, '¿El organigrama funcional de la sucursal se encuentra publicado, completo y actualizado según la estructura corporativa vigente?', 17, 28, '{"block": "4", "block_title": "4. Gestión del Personal (RRHH)", "block_weight": 0.05, "number": "4.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-4.2', '4. Gestión del Personal (RRHH)', NULL, '¿Las funciones desempeñadas operativamente por el personal corresponden de forma estricta al cargo formalizado por Recursos Humanos?', 18, 29, '{"block": "4", "block_title": "4. Gestión del Personal (RRHH)", "block_weight": 0.05, "number": "4.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-4.3', '4. Gestión del Personal (RRHH)', NULL, '¿El personal cumple con el horario de trabajo y las normas de registro de asistencia establecidas por la Compañía?', 19, 30, '{"block": "4", "block_title": "4. Gestión del Personal (RRHH)", "block_weight": 0.05, "number": "4.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-4.4', '4. Gestión del Personal (RRHH)', NULL, '¿El plan anual de vacaciones del personal está elaborado, supervisado y ejecutado para prevenir la acumulación de períodos vencidos?', 20, 31, '{"block": "4", "block_title": "4. Gestión del Personal (RRHH)", "block_weight": 0.05, "number": "4.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-4.5', '4. Gestión del Personal (RRHH)', NULL, '¿Se dispone en la sucursal de los manuales operativos y de procedimientos vigentes para consulta del personal?', 21, 32, '{"block": "4", "block_title": "4. Gestión del Personal (RRHH)", "block_weight": 0.05, "number": "4.5"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-5.1', '5. Seguridad Física y Accesos', NULL, '¿Se cuenta con servicio de vigilancia física diurna y/o nocturna formalizado o de resguardo institucional acorde al riesgo de la zona?', 22, 34, '{"block": "5", "block_title": "5. Seguridad Física y Accesos", "block_weight": 0.15, "number": "5.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-5.2', '5. Seguridad Física y Accesos', NULL, '¿El sistema de alarma y seguridad electrónica (cámaras CCTV, sensores, botones de pánico) se encuentra 100% operativo?', 23, 35, '{"block": "5", "block_title": "5. Seguridad Física y Accesos", "block_weight": 0.15, "number": "5.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-5.3', '5. Seguridad Física y Accesos', NULL, '¿Las rutas de evacuación, salidas de emergencia y extintores están claramente señalizados y con inspección vigente?', 24, 36, '{"block": "5", "block_title": "5. Seguridad Física y Accesos", "block_weight": 0.15, "number": "5.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-5.4', '5. Seguridad Física y Accesos', NULL, '¿El acceso a áreas sensibles (archivos de expedientes, cuartos técnicos y caja) está bloqueado y controlado para personas externas?', 25, 37, '{"block": "5", "block_title": "5. Seguridad Física y Accesos", "block_weight": 0.15, "number": "5.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.1', '6. Tecnología y Continuidad', NULL, '¿El cuarto o gabinete de telecomunicaciones/servidores cuenta con climatización, ventilación y protección contra factores ambientales?', 26, 39, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.2', '6. Tecnología y Continuidad', NULL, '¿El cuarto o gabinete técnico se encuentra cerrado con llave/candado y su ubicación impide el acceso de personas externas o público?', 27, 40, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.2"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.3', '6. Tecnología y Continuidad', NULL, '¿La sucursal cuenta con respaldo eléctrico operativo (UPS para equipos críticos y/o planta eléctrica) que soporte fallas comerciales?', 28, 41, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.3"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.4', '6. Tecnología y Continuidad', NULL, '¿Se cuenta con un enlace o canal de datos secundario (respaldo/contingencia) para garantizar la continuidad del servicio ante caídas?', 29, 42, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.4"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.5', '6. Tecnología y Continuidad', NULL, '¿El personal de la sucursal conoce los procedimientos elementales del Plan de Continuidad (BCP/DRP) para operar ante fallas o desastres?', 30, 43, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.5"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.6', '6. Tecnología y Continuidad', NULL, '¿El inventario de activos informáticos (PC, impresoras, periféricos) coincide con los equipos asignados e instalados en las estaciones?', 31, 44, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.6"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.7', '6. Tecnología y Continuidad', NULL, '¿Se cuenta con un procedimiento formal de desincorporación para evitar la acumulación de equipos dañados u obsoletos en la oficina?', 32, 45, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.7"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-6.8', '6. Tecnología y Continuidad', NULL, '¿Los movimientos de equipos (traslados, reparaciones, préstamos) son autorizados, registrados y notificados al área de TI/Activos?', 33, 46, '{"block": "6", "block_title": "6. Tecnología y Continuidad", "block_weight": 0.2, "number": "6.8"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-7.1', '7. Seguridad de Información', NULL, '¿Los accesos, altas y bajas del personal en los sistemas de la sucursal se gestionan mediante formularios formales de solicitud de perfil?', 34, 48, '{"block": "7", "block_title": "7. Seguridad de Información", "block_weight": 0.2, "number": "7.1"}'::jsonb),
    ('AUD_SERV_SUC', 'SS-7.2', '7. Seguridad de Información', NULL, '¿Se encuentran restringidos los puertos USB y de almacenamiento externo en las estaciones de trabajo del área de atención y caja?', 35, 49, '{"block": "7", "block_title": "7. Seguridad de Información", "block_weight": 0.2, "number": "7.2"}'::jsonb),
