-- 036: cédulas tipo cuestionario de las auditorías operativas, especiales y administrativas.
--
-- Fuente: Atributos Auditorias.xlsx (sha256 d64ef5bedf01fe16bbabeee14aa7223a10a8851cca4414acdc36e7598c910c5a).
--   - Cartelera fiscal / firmas autorizadas y Evaluación ADS: hoja «Administración CF» (ya cargada en 012 como
--     plantilla TRANSVERSAL sin uso; aquí pasan a ser cédulas de línea General).
--   - Cuestionario LOPCYMAT (5 bloques, 20 preguntas) y Administración y servicios en sucursales (7 bloques,
--     40 preguntas): hojas «LOPCYMAT» y «Servicios Sucursal», con el peso de cada bloque.
--
-- Metodología del Excel (la aplica app/modules/engagement/scoring.py):
--   Sí = 1, Parcialmente = 0,5, No = 0, N/A no cuenta. Cumplimiento del bloque = promedio de sus preguntas.
--   Índice = suma de (peso del bloque x cumplimiento). Riesgo: >= 80 % bajo, >= 60 % medio, < 60 % alto.
--   Bloque crítico («no cumple el promedio requerido»): cumplimiento por debajo del 50 %.

ALTER TABLE engagement.worksheets DROP CONSTRAINT IF EXISTS worksheets_kind_check;
ALTER TABLE engagement.worksheets ADD CONSTRAINT worksheets_kind_check CHECK (kind IN ('SUSCRIPCION', 'RECLAMO', 'SISTEMAS', 'CXP', 'CXC', 'ADMIN', 'CARTELERA', 'ADS', 'LOPCYMAT', 'SERV_SUC'));

ALTER TABLE engagement.financial_templates DROP CONSTRAINT IF EXISTS financial_templates_kind_line_check;
ALTER TABLE engagement.financial_templates ADD CONSTRAINT financial_templates_kind_line_check CHECK (
    (kind = 'TRANSVERSAL' AND line IS NULL)
    OR (kind IN ('SUSCRIPCION', 'RECLAMO') AND line IN ('AUTO', 'PATRIMONIAL', 'PERSONAL'))
    OR (kind IN ('CXP', 'CXC', 'ADMIN', 'CARTELERA', 'ADS', 'LOPCYMAT', 'SERV_SUC') AND line = 'GENERAL'));

SELECT 'AUD_CARTELERA', fc.source_id, 'Cartelera fiscal / firmas autorizadas', NULL, fc.criterion_text, row_number() OVER (ORDER BY fc.sort_order), fc.excel_row, jsonb_build_object('block', '1', 'block_title', 'Cartelera fiscal / firmas autorizadas', 'block_weight', 1, 'number', fc.source_id)
FROM engagement.financial_criteria fc WHERE fc.template_code = 'FIN_TRANSVERSAL_CARTELERA'
ON CONFLICT (template_code, source_id) DO NOTHING;

SELECT 'AUD_ADS', fc.source_id, 'Evaluación ADS', NULL, fc.criterion_text, row_number() OVER (ORDER BY fc.sort_order), fc.excel_row, jsonb_build_object('block', '1', 'block_title', 'Evaluación ADS', 'block_weight', 1, 'number', fc.source_id)
FROM engagement.financial_criteria fc WHERE fc.template_code = 'FIN_TRANSVERSAL_ADS'
ON CONFLICT (template_code, source_id) DO NOTHING;

ON CONFLICT (template_code, source_id) DO NOTHING;

